<template>
 <div><el-form label-position="top" :disabled="busy||readonly"><el-form-item label="商品名称" required :error="!draft.name.trim()?'请输入商品名称':''"><el-input v-model="draft.name" maxlength="120" aria-label="二手商品名称"/></el-form-item>
 <div class="grid"><el-form-item label="品牌"><el-autocomplete v-model="draft.brand" :fetch-suggestions="suggestBrands" :trigger-on-focus="true" aria-label="二手品牌" @input="clearSpu" @select="clearSpu"/></el-form-item><el-form-item label="型号"><el-input v-model="draft.model" maxlength="160" aria-label="二手型号" @input="clearSpu"/></el-form-item><el-form-item label="容量／规格"><el-input v-model="draft.spec" aria-label="二手规格" maxlength="160"/></el-form-item><el-form-item label="颜色"><el-input v-model="draft.color" aria-label="二手颜色" maxlength="160"/></el-form-item></div>
 <el-form-item label="二手SPU归属"><el-select v-model="draft.spuId" clearable filterable placeholder="自动按品牌和型号精确归类" aria-label="二手SPU归属" @change="selectSpu"><el-option v-for="s in data.spus" :key="s.id" :value="s.id" :label="s.name+' · '+s.code"/></el-select><p class="hint" data-used-association>{{association}}</p><el-checkbox v-if="!record" v-model="draft.newSpu" @change="draft.spuId=undefined">明确单独新建商品主体</el-checkbox></el-form-item>
 <el-form-item label="自定义分组（可不选）"><el-select v-model="draft.groupId" clearable placeholder="未分组" aria-label="二手商品分组" @clear="draft.groupId=null"><el-option v-for="g in data.groups" :key="g.id" :value="g.id" :label="g.name"/></el-select></el-form-item>
 <div class="grid"><el-form-item label="采购成本（元）"><el-input v-model="cost" inputmode="decimal" placeholder="未填写" aria-label="二手采购成本"/></el-form-item><el-form-item label="销售价格（元）"><el-input v-model="price" inputmode="decimal" placeholder="未填写，0表示免费" aria-label="二手销售价格"/></el-form-item></div>
 <p v-if="record" class="hint">设备编号：{{record.code}} · {{usedStatusLabel[record.status]}}</p><p v-else class="hint">每次保存新增一台独立实物，默认待上架；不会合并同规格设备。</p>
 <details><summary>更多信息</summary><div class="grid"><el-form-item label="序列号"><el-input v-model="draft.serial" aria-label="二手序列号" maxlength="160"/></el-form-item><el-form-item label="IMEI"><el-input v-model="draft.imei" aria-label="二手IMEI" maxlength="160"/></el-form-item></div><el-form-item label="商品图片（可选地址）"><el-input v-model="draft.image" aria-label="二手商品图片" placeholder="图片地址，可留空使用占位图标"/></el-form-item><el-form-item label="备注"><el-input v-model="draft.note" type="textarea" :rows="2" maxlength="2000" aria-label="二手备注"/></el-form-item><div v-for="(field,index) in draft.extra" :key="index" class="extra"><el-input v-model="field.key" placeholder="字段名，如电池健康度" :aria-label="'二手补充字段 '+(index+1)"/><el-input v-model="field.value" placeholder="内容" :aria-label="'二手补充内容 '+(index+1)"/><el-button text type="danger" @click="draft.extra.splice(index,1)">移除</el-button></div><el-button :disabled="draft.extra.length>=20" plain @click="draft.extra.push({key:'',value:''})">添加补充信息</el-button></details>
 </el-form><el-alert v-if="error" :title="error" type="error" :closable="false" data-used-form-error/><p v-if="problem&&!readonly" class="error">{{problem}}</p><div class="footer"><el-button :disabled="busy" @click="emit('close')">{{readonly?'关闭':'取消'}}</el-button><el-button v-if="!readonly" type="primary" :disabled="busy||!!problem" :loading="busy" data-save-used-sku @click="save">保存二手商品</el-button></div></div>
</template>
<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {useCatalogStore} from '../../stores/catalog'
import {emptyUsedInput,inputProblem,resolveUsedSpu,parseUsedPrice,usedStatusLabel,type UsedInput,type UsedSku,type UsedGoods} from '../../domain/usedGoods'
const props=defineProps<{data:UsedGoods;record?:UsedSku;seed?:UsedInput;readonly?:boolean}>(),emit=defineEmits<{saved:[id:string];close:[]}>(),store=useCatalogStore(),draft=ref<UsedInput>(JSON.parse(JSON.stringify(props.seed||emptyUsedInput()))),busy=ref(false),error=ref(''),owner=JSON.stringify([store.activeUserId,store.previewUserId]),requestId=crypto.randomUUID()
if(props.record){const s=props.record,p=props.data.spus.find(p=>p.id===s.spuId)!;draft.value={...JSON.parse(JSON.stringify(s)),brand:p.brand,model:p.model}}
const cost=ref(draft.value.costCents===null?'':(draft.value.costCents/100).toFixed(2)),price=ref(draft.value.priceCents===null?'':(draft.value.priceCents/100).toFixed(2)),stamp=()=>JSON.stringify([draft.value,cost.value,price.value]),initial=ref(stamp()),isDirty=computed(()=>!props.readonly&&initial.value!==stamp()),alive=ref(true)
const input=computed<UsedInput>(()=>({...draft.value,costCents:parseUsedPrice(cost.value)??null,priceCents:parseUsedPrice(price.value)??null,groupId:draft.value.groupId||null})),matches=computed(()=>resolveUsedSpu(props.data,input.value)),problem=computed(()=>parseUsedPrice(cost.value)===undefined||parseUsedPrice(price.value)===undefined?'金额须为非负数，最多两位小数':inputProblem(props.data,input.value)||(!input.value.spuId&&!input.value.newSpu&&matches.value.length>1?'存在多个匹配的SPU，请明确选择归属':''))
const association=computed(()=>input.value.spuId?'明确关联：'+(props.data.spus.find(s=>s.id===input.value.spuId)?.name||'SPU已失效'):input.value.newSpu?'本次明确新建二手SPU':matches.value.length===1?'自动复用：'+matches.value[0]!.name:matches.value.length>1?'发现多个匹配，请从上方选择':!input.value.brand.trim()||!input.value.model.trim()?'品牌型号未填齐，本次新建SPU；也可明确选择已有主体':'没有精确匹配，将自动新建二手SPU')
function clearSpu(){draft.value.spuId=undefined;draft.value.newSpu=false}
function selectSpu(id:string){const s=props.data.spus.find(s=>s.id===id);if(s){draft.value.brand=s.brand;draft.value.model=s.model;draft.value.newSpu=false}}
function suggestBrands(query:string,done:(rows:{value:string}[])=>void){done([...new Set(props.data.spus.map(s=>s.brand).filter(Boolean))].filter(v=>v.toLowerCase().includes(query.toLowerCase())).map(value=>({value})))}
async function save(){if(busy.value||problem.value)return;busy.value=true;error.value='';const expected=stamp();try{const result=await store.saveUsedSku(input.value,props.record?.revision||0,requestId,()=>alive.value&&owner===JSON.stringify([store.activeUserId,store.previewUserId])&&stamp()===expected);if(!alive.value)return;if(!result.ok){error.value=result.message||'保存失败，输入保留';return}if('record'in result&&result.record){initial.value=stamp();busy.value=false;emit('saved',result.record.id)}}catch(e){if(alive.value)error.value=String(e)}finally{busy.value=false}}
watch([draft,cost,price],()=>error.value='',{deep:true})
onBeforeUnmount(()=>{alive.value=false})
defineExpose({isDirty,busy})
</script>
<style scoped>.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.el-select,.el-autocomplete{width:100%}.hint{font-size:12px;color:var(--el-text-color-secondary);line-height:1.6;margin:8px 0}.extra{display:flex;gap:8px;margin-bottom:10px}summary{cursor:pointer;margin:10px 0 18px}.error{font-size:13px;color:var(--el-color-danger)}.footer{position:sticky;bottom:0;background:var(--el-bg-color);display:flex;justify-content:flex-end;gap:8px;padding:16px 0;margin-top:16px;border-top:1px solid var(--el-border-color-light)}@media(max-width:600px){.grid{grid-template-columns:1fr}.extra{flex-wrap:wrap}}</style>
